823	LiaStarExtension::MainEnum& LiaStarExtension::getMainEnum(Node lambda)
824	{
825	  // Return the main-solver enumeration state for `lambda`, creating it and
826	  // queueing its seed lemmas on first use. The construction of the base
827	  // predicate and the skolems mirrors `getSubsolver`.
828	  auto it = d_mainEnums.find(lambda);
829	  if (it != d_mainEnums.end())
830	  {
831	    return it->second;
832	  }
833	  MainEnum& en = d_mainEnums[lambda];
834	
835	  // The base is the membership predicate (with ites and negations eliminated)
836	  // conjoined with the non-negativity of the lambda's variables.
837	  Node base = LiaStarUtils::removeItesAndNots(lambda[1], &d_env);
838	  std::vector<Node> conjuncts{base};
839	  for (Node var : lambda[0])
840	  {
841	    conjuncts.push_back(d_nm->mkNode(Kind::GEQ, var, d_zero));
842	  }
843	  base =
844	      conjuncts.size() == 1 ? conjuncts[0] : d_nm->mkNode(Kind::AND, conjuncts);
845	
846	  // The lambda's bound variables appear free in `base`. A lemma with free
847	  // (bound) variables cannot be sent to the main solver, so we replace them
848	  // with fresh skolems and remember the mapping so the disjunct built from
849	  // the model can be substituted back into bound-variable space.
850	  for (Node var : lambda[0])
851	  {
852	    if (var.getKind() == Kind::BOUND_VARIABLE)
853	    {
854	      en.from.push_back(var);
855	      en.to.push_back(d_nm->mkDummySkolem("liastarEnum", var.getType()));
856	    }
857	  }
858	  if (!en.from.empty())
859	  {
860	    base = base.substitute(
861	        en.from.begin(), en.from.end(), en.to.begin(), en.to.end());
862	  }
863	  en.base = base;
864	
865	  // The first stage guard of the enumeration: a decision variable biased to
866	  // true, like the guard of the tentative reduction in `processDisjunct`.
867	  // While a cell of the predicate is still uncovered, the solver can satisfy
868	  // the current stage guard and its model places the skolems in such a cell;
869	  // once every cell is covered, the guarded lemmas force it false.
870	  Node g = d_nm->mkDummySkolem("liastarEnumGuard", d_nm->booleanType());
871	  g = d_astate.getValuation().ensureLiteral(g);
872	  d_im.preferPhase(g, true);
873	  en.guard = g;
874	  Node split = g.orNode(g.notNode());
875	  if (d_proofGen != nullptr)
876	  {
877	    d_proofGen->registerSplit(split, g);
878	  }
879	  d_im.addPendingLemma(
880	      split, InferenceId::ARITH_LIA_STAR_SPLIT, d_proofGen.get());
881	  // the guarded predicate: guard => base
882	  addEnumLemma(g.impNode(base));
883	  return en;
884	}
